import{_ as e,o as l,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const S=JSON.parse('{"title":"2019-09-03 :: Crimson SeaStor OSD Weekly Meeting","description":"","frontmatter":{"title":"2019-09-03 :: Crimson SeaStor OSD Weekly Meeting","date":"2019-09-03T00:00:00.000Z","updated":"2019-09-07T00:00:00.000Z","tags":["Ceph","分布式存储","性能测试","GitHub API","调试"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-09-03_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","filePath":"posts/2019/2019-09-03_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","lastUpdated":1780460162000}'),r={name:"posts/2019/2019-09-03_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md"};function s(n,i,a,_,p,u){return l(),t("div",null,[...i[0]||(i[0]=[o('<h3 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h3><p>会议纪要</p><p>会议时间：2019年9月3日 会议地点：[请填写会议地点] 参会人员：Keefer，其他研发人员</p><p>会议内容：</p><ol><li><p><strong>性能测试与集成</strong></p><ul><li>Keefer汇报了上周的性能测试工作，比较了基准测试与改进后的结果。</li><li>计划将测试结果集成到Jenkins中，并探索不同的集成方法，如GitHub API。</li><li>预计本周内完成集成，以便在GitHub上展示测试结果的差异。</li></ul></li><li><p><strong>GitHub API使用</strong></p><ul><li>讨论了使用GitHub API展示测试结果的可行性，包括在PR页面添加检查标签。</li><li>决定利用GitHub API的灵活性来展示更详细的测试结果。</li></ul></li><li><p><strong>调试与代码问题</strong></p><ul><li>Keefer在调试过程中遇到问题，特别是在GDB环境中。</li><li>讨论了代码在不同环境下的行为差异，以及如何解决这些问题。</li></ul></li><li><p><strong>Crimson项目</strong></p><ul><li>讨论了Crimson项目的以下议题： <ul><li>观察通知机制的实施。</li><li>对大PG对象上下文的细粒度锁定。</li><li>系统的预定订单。</li></ul></li><li>讨论了即将到来的峰会，并确认了参会人员。</li></ul></li><li><p><strong>Sister项目</strong></p><ul><li>讨论了Sister项目的以下议题： <ul><li>修复一个小的bug。</li><li>支持UNIX域套接字。</li><li>关于连接接受的讨论，包括POSIX套接字的处理方式。</li></ul></li><li>决定将修复的代码提交到Sister项目的分支，并定期与上游合并。</li></ul></li><li><p><strong>性能测试</strong></p><ul><li>讨论了在性能测试中使用Rkt和CBT进行性能比较的必要性。</li><li>提出在测试中关闭单元测试以避免性能影响的建议。</li></ul></li><li><p><strong>后续行动计划</strong></p><ul><li>Keefer将继续工作，解决调试问题和性能测试。</li><li>其他研发人员将继续工作在各自的项目中，并准备即将到来的峰会。</li></ul></li></ol><p>备注：</p><ul><li>会议中提到了一些计算机科学/ceph相关领域的英文关键词，包括：GitHub API, Jenkins, performance tests, POSIX sockets, UNIX domain sockets, PG objects, connection acceptance, debugging, performance comparison, Rkt, CBT等。</li></ul>',7)])])}const g=e(r,[["render",s]]);export{S as __pageData,g as default};
